// Determine the paging mode from the last paging-related option that was
// provided. Configuration file arguments are inserted before command-line
// arguments, so this ensures that -P and -pp take precedence over a
// --paging setting from the configuration file.
let mut paging_choice: Option<(usize, Option<PagingMode>)> = None;

if self.matches.occurrences_of("paging") > 0 {
    if let Some(index) = self.matches.indices_of("paging").and_then(|mut i| i.last()) {
        let mode = match self.matches.value_of("paging") {
            Some("always") => Some(PagingMode::Always),
            Some("never") => Some(PagingMode::Never),
            Some("auto") | None => None,
            _ => unreachable!("other values for --paging are not allowed"),
        };
        paging_choice = Some((index, mode));
    }
}

if let Some(index) = self
    .matches
    .indices_of("no-paging")
    .and_then(|mut i| i.last())
{
    if paging_choice.map_or(true, |(i, _)| index > i) {
        paging_choice = Some((index, Some(PagingMode::Never)));
    }
}

// If -pp is passed, the pager should be disabled, but only if it comes
// after an explicit --paging option.
if self.matches.occurrences_of("plain") > 1 {
    if let Some(index) = self.matches.indices_of("plain").and_then(|mut i| i.last()) {
        if paging_choice.map_or(true, |(i, _)| index > i) {
            paging_choice = Some((index, Some(PagingMode::Never)));
        }
    }
}

let paging_mode = match paging_choice {
    Some((_, Some(mode))) => mode,
    Some((_, None)) | None => {
        if inputs.iter().any(Input::is_stdin) {
            // If we are reading from stdin, only enable paging if we write to an
            // interactive terminal and if we do not *read* from an interactive
            // terminal.
            if self.interactive_output && !atty::is(Stream::Stdin) {
                PagingMode::QuitIfOneScreen
            } else {
                PagingMode::Never
            }
        } else if self.interactive_output {
            PagingMode::QuitIfOneScreen
        } else {
            PagingMode::Never
        }
    }
};

